import React, { useState } from 'react';

const ForumForm = ({ onSubmit }) => {
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [categoryId, setCategoryId] = useState('');
    const [banner, setBanner] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        onSubmit({ name, description, category_id: categoryId, banner });
    };

    return (
        <form onSubmit={handleSubmit}>
            <label>
                Name:
                <input type="text" value={name} onChange={(e) => setName(e.target.value)} required />
            </label>
            <label>
                Description:
                <textarea value={description} onChange={(e) => setDescription(e.target.value)} required />
            </label>
            <label>
                Category ID:
                <input type="text" value={categoryId} onChange={(e) => setCategoryId(e.target.value)} required />
            </label>
            <label>
                Banner URL:
                <input type="text" value={banner} onChange={(e) => setBanner(e.target.value)} />
            </label>
            <button type="submit">Create Forum</button>
        </form>
    );
};

export default ForumForm;
